  const radius = maxRadius - i * 20;
  const context = ctx.createRadialGradient(
    centerX, centerY,
    radius - 10,
    centerX, centerY,
    radius + 10
  );

  const shade = (i % 2 === 0) ? 1 : 0.7;
  context.addColorStop(0, colors[i]);
  context.addColorStop(1, colors[i].replace('#', '#88'));

  ctx.fillStyle = context;
  ctx.beginPath();
  ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
  ctx.fill();
}

// Draw radial patterns
ctx.strokeStyle = '#ffffff';
ctx.lineWidth = 2;
for (let i = 0; i < 8; i++) {
  const angle = (i / 8) * Math.PI * 2;
  const startX = centerX + Math.cos(angle) * (maxRadius - 30);
  const startY = centerY + Math.sin(angle) * (maxRadius - 30);

  ctx.beginPath();
  ctx.moveTo(startX, startY);
  for (let j = 0; j < 8; j++) {
    const subAngle = (j / 8) * Math.PI * 2;
    const endX = centerX + Math.cos(subAngle) * (maxRadius - 10);
    const endY = centerY + Math.sin(subAngle) * (maxRadius - 10);
    ctx.lineTo(endX, endY);
