// Draw spiral in cool tones
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

// Colors for cool tones
const colors = [
  '#0a1929', // deep blue
  '#1a3a5a', // navy
  '#2a5a7a', // indigo
  '#3a7a9a', // violet
  '#4a9abb', // blue
  '#5aaebc'  // cyan
];

// Function to draw spiral segment
function drawSpiralSegment(radius, angle, color) {
  const x = centerX + Math.cos(angle) * radius;
  const y = centerY + Math.sin(angle) * radius;

  // Draw segment with gradient effect
  const gradient = ctx.createLinearGradient(x, y, x + 5, y + 5);
  gradient.addColorStop(0, color);
  gradient.addColorStop(1, '#0a0a2a');

  ctx.fillStyle = gradient;
  ctx.fillRect(x - 2, y - 2, 5, 5);
}

// Draw spiral
let radius = 0;
const angleStep = 0.02;
const numSegments = 100;

for (let i = 0; i < numSegments; i++) {
  const angle = i * angleStep;
  radius += 3;

  if (radius > maxRadius) {
    radius = maxRadius;
  }

  // Alternate between two colors for visual interest
  const colorIndex = i % 2 === 0 ? 0 : 1;
  drawSpiralSegment(radius, angle, colors[colorIndex]);
}

// Add some subtle shading
ctx.fillStyle = '#050a1a';
for (let i = 0; i < 20; i++) {
  const r = 5 + i * 2;
  const a = i * 0.1;
  drawSpiralSegment(r, a, '#0a1a2a');
}

